/**
 * 墨西哥帅哥游slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        particle_node:cc.Node,
    },

    onLoad () {
        this._super();
        this.particle_node = this.node.getChildByName("particle_node");
        this.particle_node.active = false;
    },

    //重写
    StartMove:function(){
        this._super();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            SlotsFacade.soundMgr.playBgm();
        }
    },

    //重写：小游戏取的数据不一样
    onMsgSpine:function(msg){
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },
    
    showAllSymbolsToNormal() {
        this._reels.forEach(element => {
            element._symbols.forEach(s => {
                s.ShowKuang(false);
                s.ShowNormal();
            });
        });
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx 
     */
    getIdxGlobalPos(idx) {
        let col = (idx - 1) % this._col;
        let row = this._row - Math.floor((idx -1)/this._col) -1
        let reel = this._reels[col];
        let pos = reel.GetSymbolPosByRow(row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 抖动效果
     */
    async bonusShake() {
        let spinData = SlotsFacade.dm.getSpinData();
        if(!spinData.bonusResult) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("reel_notify_s");
        let shakeTime = 1.3;
        let shakeOffset = 10;
        this.particle_node.active = true;
        for(let i=0; i<6; i++) {
            let p = this.particle_node.getChildByName("p" + (i+1)).getComponent(cc.ParticleSystem);
            p.resetSystem();
        }
        Global.shakeNode(this.node, shakeOffset, shakeTime);
        await SlotsFacade.delayTime(1.1)
    },

    allSymbolsToStartMove() {
        for(let i=0; i<this._reels.length; i++) {
            let symbols = this._reels[i]._symbols;
            for(let j=0; j<symbols.length; j++) {
                symbols[j].StartMove();
            }
        }
    },

    /**
     * 播放打鼓奖励
     */
    async playBonusResult() {
        let spinData = SlotsFacade.dm.getSpinData();
        if(!spinData.bonusResult) {
            return;
        }
        this.allSymbolsToStartMove();
        let bonusResult = spinData.bonusResult;
        let cards = SlotsFacade.dm.getColCards(bonusResult.col-1);
        let index = cards.indexOf(this._cfg.scatterId);
        if(index != -1) {
            let idx = index*this._cfg.col + bonusResult.col;
            let symbol = this.GetSymbolByIdx(idx);
            let addfreeCnt = false;
            if(SlotsFacade.dm.hasFree() && bonusResult.type == 1){
                addfreeCnt = bonusResult.freeCnt == 2;
            }
            await symbol.playGuBonusReel(addfreeCnt);
            SlotsFacade.drumsGame.reelBingo(bonusResult.col);
            // SlotsFacade.soundMgr.playEffect("bell");
            await SlotsFacade.delayTime(1);
            if(bonusResult.type == 3 && bonusResult.winCoin) {
                await this.addBonusCoin(bonusResult.winCoin);

                //金币刷新
                cc.vv.gameData.AddCoin(bonusResult.winCoin);
                cc.vv.gameData.GetSlotsScript()._topScript.ShowCoin();
            }
            if(bonusResult.type == 1 && SlotsFacade.dm.canCollect() && SlotsFacade.dm.isFistTriggerFree()) {
                await SlotsFacade.drumsGame.updateCollectProgress();
            }
        }
    },

    async addBonusCoin(winCoin) {
        let nWin = winCoin;
        let nTotal = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
    }
});
