let BonusType = {
    FreeGame: 1,  // 免费游戏
    Wheel: 2,  // 转轴
    Coin: 3,  // 多倍下注额
}

cc.Class({
    extends: cc.Component,

    properties: {
        collect:cc.Node,
        bonus_tips_node:cc.Node,
        bonus_item:cc.Node,
        character:cc.Node,
        collect_tips:cc.Node,
        spine_character:cc.Node,

        _isOpenCollect:false, // 是否打开收集
        _bonusReels:[], //
        _bonusWheels:[],
        _collectStepItems:[] // 收集进度
    },

    onLoad() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.collect.on(cc.Node.EventType.TOUCH_END, ()=>{
            // let tips = this.collect.getChildByName("collect_tips");
            this._showCollectTips(!this.collect_tips.active);
            this._clickCollect();
        }, this);

        for(let i=0; i<3; i++) {
            let reel = this.bonus_item.getChildByName("reel" + (i+1));
            let cmp = reel.addComponent("LordCaesar_BonusReel1");
            this._bonusReels.push(cmp);
        }
        for(let i=0; i<2; i++) {
            let wheel = this.bonus_item.getChildByName("wheel" + (i+1));
            let cmp = wheel.addComponent("LordCaesar_BonusReel2");
            cmp.setType(i+1);
            this._bonusWheels.push(cmp);
        }

        this._collectStepItems = [];
        for(let i=0; i<16; i++) {
            this._collectStepItems.push(this.collect.getChildByName("step" + (i+1)));
        }
    },

    start() {
        // 显示收集条
        this.showCollect(true);
        // 显示收集进度
        this.initCollectProgress();
        // 初始化bonus reel
        this.initBonusReels();
        // 初始化bonus wheel
        this.initBonusWheels();
        if(SlotsFacade.dm.hasFree()) {
            this.toFreeGame();
        }else {
            this.toNormalGame();
        }
    },

    /**
     * 初始化显示bonu sreel
     */
    initBonusReels() {
        let items = SlotsFacade.dm.extraBonusRow.items;
        let reelsData = [items[0], items[2], items[4]];
        let bet = SlotsFacade.dm.GetTotalBet()
        for(let i=0; i<reelsData.length; i++) {
            let reel = this._bonusReels[i];
            let vo = reelsData[i];
            if(vo.type == BonusType.FreeGame) {
                reel.setCurrSymbol(0);
            }else {
                reel.setCurrSymbol(bet * vo.mult);
            }
        }
    },

    /**
     * 初始化bonus wheel
     */
    initBonusWheels() {
        let hasFree = SlotsFacade.dm.hasFree();
        for(let i=0; i<this._bonusWheels.length; i++) {
            let wheel = this._bonusWheels[i];
            wheel.setUnlock(hasFree);
        }
    },

    /**
     * 显示提示
     */
    _showCollectTips(boo) {
        let tips = this.collect_tips;
        if(boo) {
            if(tips.active) {
                return;    
            }
            tips.active = true;
            tips.stopAllActions();
            tips.opacity = 0;
            cc.tween(tips)
                .to(1, {opacity:0xff})
                .delay(2)
                .to(1, {opacity:0})
                .call(()=>{
                    tips.active = false;
                })
                .start();
        }else {
            if(!tips.active) {
                return;    
            }
            tips.active = true;
            tips.stopAllActions();
            cc.tween(tips)
                .to(1, {opacity:0})
                .call(()=>{
                    tips.active = false;
                })
                .start();
        }
    },

    /**
     * 显示收集界面
     * @param isInit
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        let lock = this.collect.getChildByName("lock").getComponent(sp.Skeleton);
        if(boo) {
            if(!this._isOpenCollect) {
                if(isInit) {
                    lock.node.active = false;
                }else {
                    lock.node.active = true;
                    SlotsFacade.soundMgr.playEffect("ad_board_change");
                    lock.setAnimation(0, "animation2", false);
                }
                this._showCollectTips(true);
            }
        }else {
            if(isInit) {
                lock.node.active = true;
                lock.setAnimation(0, "animation1", true);
            }else {
                if(this._isOpenCollect) {
                    SlotsFacade.soundMgr.playEffect("ad_board_change");
                    lock.node.active = true;
                    lock.setAnimation(0, "animation3", false);
                    lock.addAnimation(0, "animation1", true);
                    this._showCollectTips(false);
                }
            }
        }
        this._isOpenCollect = boo;
    },

    /**
     * 初始化收集进度条
     */
    initCollectProgress() {
        let bonusTrail = SlotsFacade.dm.bonusTrail;
        let count = bonusTrail.count;
        for(let i=0; i<16; i++) {
            let item = this._collectStepItems[i];
            item.getChildByName("icon").active = i<count;
        }
    },

    /**
     * 更新收集进度条
     */
    async updateCollectProgress() {
        let bonusTrail = SlotsFacade.dm.bonusTrail;
        let count = bonusTrail.count;
        let item = this._collectStepItems[count - 1];
        if(!item) {
            return;
        }
        let spNode = item.getChildByName("spine");
        let icon = item.getChildByName("icon");
        if(spNode){
            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
            spine.node.active = true;
            let aniName = "animation1";
            let soundName = "lightup1";
            if(bonusTrail.megaIdx.includes(count)) {
                aniName = "animation2";
                soundName = "lightup2";
            }else if(bonusTrail.superBonus.includes(count)) {
                aniName = "animation3";
                soundName = "lightup2";
            }
            SlotsFacade.soundMgr.playEffect("soundName");
            spine.setAnimation(0, aniName, false);
            await new Promise(res=>{
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                    item.getChildByName("icon").active = true;
                    res();
                })
            });
        } else {
            item.getChildByName("icon").active = true;
            icon.setScale(0);
            await new Promise(res=>{
                cc.tween(icon)
                    .to(0.5, {scale:0.85})
                    .delay(0.2).call(()=>{res()}).start()
            });
        }
    },

    /**
     * 改变bonus reel
     */
    async changeBonusReel() {
        let items = SlotsFacade.dm.extraBonusRow.items;
        let reelsData = [items[0], items[2], items[4]];
        let bet = SlotsFacade.dm.GetTotalBet()
        for(let i=0; i<reelsData.length; i++) {
            let reel = this._bonusReels[i];
            let vo = reelsData[i];
            if(vo.type == BonusType.FreeGame) {
                reel.reel(0);
            }else {
                reel.reel(bet * vo.mult);
            }
        }
        await SlotsFacade.delayTime(0.6);
    },

    /**
     * 点击收集条
     */
    _clickCollect(){
        if(!this._isOpenCollect) {
            // 如果在免费中 返回
            if(SlotsFacade.dm.hasFree()) {
                return;
            }
            // 如果spin不可点击 返回
            if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
                return;
            }
            // 自动旋转模式 返回
            if(SlotsFacade.dm.GetAutoModelTime() > 0) {
                return;
            }

            let betList = SlotsFacade.dm.GetBetMults();
            let needBet = SlotsFacade.dm.getDeskInfo().needBet;
            // 金币不足
            if(needBet > betList.length) {
                return;
            }
            cc.vv.gameData.GetBottomScript().SetBetIdx(needBet);
        }
    },


    /**
     * 打鼓
     */
    async hothot() {
        let spinData = SlotsFacade.dm.getSpinData();
        let multipleExtraBonus = spinData.multipleExtraBonus;
        if(multipleExtraBonus) {
            this.spine_character.getComponent(sp.Skeleton).setAnimation(0, "skill01", false);
            this.spine_character.getComponent(sp.Skeleton).addAnimation(0, "idle", true);

            await cc.vv.gameData.awaitTime(0.8);
            // let spineGu = this.character.getChildByName("dagu").getComponent(sp.Skeleton);
            // spineGu.setAnimation(0, "animation2", false);
            // 打鼓
            // await new Promise(res=>{
            //     this.spine_character.setCompleteListener(()=>{
            //         this.spine_character.setCompleteListener(null);
            //         res();
            //     });
            // });
            // 出现倍数
            SlotsFacade.soundMgr.playEffect("multiply_active");
            let spineMul = this.character.getChildByName("shuzi_x" + multipleExtraBonus).getComponent(sp.Skeleton);
            let spineZhuanGuang = this.character.getChildByName("zhuanguang").getComponent(sp.Skeleton);
            spineMul.node.active = true;
            spineMul.setAnimation(0, `animation${multipleExtraBonus}_1`, false);
            spineMul.addAnimation(0, `animation${multipleExtraBonus}_2`, true);
            await new Promise(res=>{
                spineMul.setCompleteListener(()=>{
                    spineMul.setCompleteListener(null);
                    spineZhuanGuang.node.active = true;
                    res();
                });
            });
            // 发射倍数
            let items = SlotsFacade.dm.extraBonusRow.items;
            let reelsData = [items[0], items[2], items[4]];
            let spine_trigger = this.character.getChildByName("spine_trigger").getComponent(sp.Skeleton);
            spine_trigger.node.active = true;
            for(let i=0; i<reelsData.length; i++) {
                let vo = reelsData[i];
                if(vo.type == BonusType.Coin) {
                    SlotsFacade.soundMgr.playEffect("bonus_shot");
                    spine_trigger.setAnimation(0, "animation" + (i+1), false);
                    await SlotsFacade.delayTime(0.6);
                    let reel = this._bonusReels[i];
                    reel.setMultiple(multipleExtraBonus)
                    reel.playSelectEffect(true, true);
                    await SlotsFacade.delayTime(0.4);
                }
            }
        }
    },

    /**
     * 切换到正常效果
     */
    toNormal() {
        let spinData = SlotsFacade.dm.getSpinData();
        let multipleExtraBonus = spinData.multipleExtraBonus;
        if(multipleExtraBonus) {
            // 隐藏bonusReels 选中效果
            this._bonusReels.forEach(element => {
                element.playSelectEffect(false);
            });
            // 还原鼓动画
            //- let spineGu = this.character.getChildByName("dagu").getComponent(sp.Skeleton);
            //- spineGu.setAnimation(0, "animation1", true);
            // 还原倍数
            let spineMul = this.character.getChildByName("shuzi_x" + multipleExtraBonus).getComponent(sp.Skeleton);
            spineMul.setAnimation(0, `animation${multipleExtraBonus}_3`, false);
            spineMul.setCompleteListener(()=>{
                spineMul.setCompleteListener(null);
                spineMul.node.active = false;
            });
            // 还原光效
            let spineZhuanGuang = this.character.getChildByName("zhuanguang").getComponent(sp.Skeleton);
            spineZhuanGuang.node.active = false;
        }
    },

    /**
     * 
     * @param {*} reelIndx 
     */
    reelBingo(reelIndx){
        let item = [
            this._bonusReels[0],
            this._bonusWheels[0],
            this._bonusReels[1],
            this._bonusWheels[1],
            this._bonusReels[2],
        ][reelIndx-1];
        item.playSelectEffect(true, false);
    },

    /**
     * 解锁wheel
     */
    unlockWheel() {
        SlotsFacade.soundMgr.playEffect("free_unlock");
        this._bonusWheels.forEach(element => {
            element.toUnlock();
        });
    },

    toNormalGame() {
        this.initBonusWheels();
        this.bonus_tips_node.active = false;
        this.collect.active= true;
    },

    toFreeGame() {
        this.collect.active= false;
        this.bonus_tips_node.active = true;
        let freeType = SlotsFacade.dm.getFreeType();
        let megaTips = this.bonus_tips_node.getChildByName("mega_tips");
        let superTips = this.bonus_tips_node.getChildByName("super_tips");
        megaTips.active = freeType == 2;
        superTips.active = freeType == 3;
    }
})
