/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        bonusTrail:null,
        extraBonusRow: null,
        wheelGame:null,
    },

    init(deskInfo,gameId,gameJackpot) {
        this.bonusTrail = deskInfo.bonusTrail;
        this.extraBonusRow = deskInfo.extraBonusRow;
        this.wheelGame = deskInfo.wheelGame;
        this._super(deskInfo,gameId,gameJackpot);
    },

    OnRcvNetSpine:function(msg){
        this.wheelGame = null;
        if(msg.code == 200){
            this.bonusTrail = msg.bonusTrail;
            this.extraBonusRow = msg.extraBonusRow;
            this.wheelGame = msg.wheelGame;
        }
        this._super(msg);
    },

    SetSubGameData:function(data){
        this._subGame = data
    },

    GetSubGameData:function(){
        return this._subGame
    },

    getSpinData() {
        return this._gameInfo;
    },

    ////////////////////////免费相关///////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let bonusResult = this._gameInfo.bonusResult;
        if(bonusResult && bonusResult.type == 1) {
           return bonusResult.freeCnt;
        }
        return 0;
    },
    
    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    getBonusIndexs() {
        if(!this.bonusData) {
            return [];
        }
        let ret = [];
        let scatterId = this.getGameCfg().scatterId;
        let cards = this.getSpinData().resultCards;
        for(let i=0; i<cards.length; i++) {
            let c = cards[i];
            if(c == scatterId) {
                ret.push(i+1);
            }
        }
        return ret;
    },

    /**
     * 获取1列cards列数据
     * @param {*} colIndex 0~4
     */
    getColCards(colIndex) {
        let data = this._gameInfo.resultCards;
        let ret = [];
        let cfg = this.getGameCfg();
        let col = cfg.col;
        let row = cfg.row;
        for(let i=0; i<row; i++) {
            ret.push(data[colIndex + i*col]);
        }
        return ret;
    },

    /**
     * 获取免费类型
     */
    getFreeType() {
        let ret = 1;
        if(this.hasFree()) {
            let count = this.bonusTrail.count;
            if(this.bonusTrail.superBonus.includes(count)) {
                ret = 3;
            } else if(this.bonusTrail.megaIdx.includes(count)) {
                ret = 2;
            }else {
                ret = 1;
            }
        }
        return ret;
    },

    ///////////////////////////收集游戏/////////////////
    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    ///////////////////////////jp game //////////////////
    /**
    *  获取jackport的值
    */
    getJpValue(jpType) {
        let baseArr = cc.vv.AppData.getGameJackpot(this._gameId);
        //val: 0:mini 1:minor 2:major 3:grand(mega) 4:self define
        let jpBase = 10;
        if (baseArr) {
            jpBase = baseArr[jpType]
        }
        return this.GetTotalBet() * jpBase;
    },

    /////////////////////////打鼓
    getBonusCoin() {
        let bonusResult = this.getSpinData().bonusResult;
        if(!bonusResult || !bonusResult.winCoin) {
            return 0;
        }
        return bonusResult.winCoin;
    },
});
