cc.Class({
    extends: cc.Component,

    properties: {
        itemHeight:69,
        symbols:[], 
        val:0, // 当前得值
        _currSymbol:null, // 当先显示得symbol
        isLoaded:false,

        select_effect:sp.Skeleton,  // 选中效果
        credit_liuguang:sp.Skeleton, // 免费icon流光效果
    },

    onLoad() {
        this.select_effect = this.node.getChildByName("select_effect").getComponent(sp.Skeleton);
        this.select_effect.node.active = false;
        this.credit_liuguang = this.node.getChildByName("credit_liuguang").getComponent(sp.Skeleton);
        this.credit_liuguang.node.active = false;

        for(let i=0; i<2; i++) {
            let s = this.node.getChildByName("symbol" + (i+1));
            this.symbols.push(s);
        }
        this._currSymbol = this.symbols[0];

        this.isLoaded = true;
        this.setCurrSymbol(this.val);
    },

    setCurrSymbol(val) {
        this.val = val;
        if(!this.isLoaded) {
            return;
        }
        this.updateSymbol(this._currSymbol, this.val);
    },

    /**
     * 设置倍数
     * @param {*} mul 
     */
    setMultiple(mul) {
        this.val = mul*this.val;
        this.updateSymbol(this._currSymbol, this.val);
    },

    /**
     * 显示即将显示得symbol
     * 下注倍数 [0~5) 铁背景 [0~10) 铜背景 [0~10) 铜背景
     * @param {*} symbol 
     * @param {*} val 0-免费游戏
     */
    updateSymbol(symbol, val) {
        let s = symbol;
        let img = s.getComponent("ImgSwitchCmp");
        let label = s.getChildByName("label");
        label.active = val > 0;
        // 设置图片背景
        if(val) {
            let bet = SlotsFacade.dm.GetTotalBet();
            let mul = val/bet;
            if(mul >= 20) {
                img.setIndex(4);
            }else if(mul >= 10) {
                img.setIndex(3);
            }else if(mul >= 5) {
                img.setIndex(2);
            }else {
                img.setIndex(1);
            }
            // 设置文本
            label.getComponent(cc.Label).string = Global.formatNumShort(val);
        }else {
            img.setIndex(0);
        }
    },

    /**
     * 开始旋转
     * @param {*} val 
     */
    reel(val) {
        this.val = val;
        this._currSymbol = this.symbols[1];
        this.updateSymbol(this._currSymbol, this.val);
        let symbols = this.symbols.concat();
        let temp = this.symbols[0];
        this.symbols[0] = this.symbols[1];
        this.symbols[1] = temp;

        // 设置位置
        for(let i=0; i<symbols.length; i++) {
            let s = symbols[i];
            s.y = i*this.itemHeight;
        }

        cc.tween(symbols[0])
            .to(0.5, {y: -this.itemHeight})
            .start();

        cc.tween(symbols[1])
            .to(0.5, {y: 0})
            .call(()=>{
                let bet = SlotsFacade.dm.GetTotalBet();
                let mul = val/bet;
                if(this.val == 0 || mul >=5) {
                    this.credit_liuguang.node.active = true;
                    this.credit_liuguang.setAnimation(0, "animation", false);
                }
            })
            .start();
    },

    /**
     * 播放选中特效
     * @param {*} boo 显示隐藏
     * @param {*} loop 是否循环
     */
    playSelectEffect(boo, loop) {
        this.select_effect.node.active = boo;
        if(boo) {
            loop = loop || false;
            this.select_effect.setAnimation(0, "animation", loop);
        }
    }
})