// 卷轴配置 0~4 mini~grand
let ReelCfg = [
    [1,2,3,2,1,0,1,2,3,2,1,0], //中mini的卷轴
    [0,1,2,3,2,1,0,1,2,3,2,1], //中minor的卷轴
    [1,0,1,2,3,2,1,0,1,2,3,2], //中major的卷轴
    [2,1,0,1,2,3,2,1,0,1,2,3], //中grand的卷轴
];

cc.Class({
    extends: cc.Component,

    properties: {
        panel:cc.Node,
        symbol:cc.Node,
        reel:cc.Node,
        popup_start:cc.Node,
        win_flag:cc.Node,
        jp_node:cc.Node,

        _cbHandler:null,
        _reelLen:11, // 卷轴元素
        _itemHeight:163,
        _symbolItems:[],
        _reelResult:null, // 卷轴结果
        _moveObj:null, // 移动总距离
        _jpData:null, // 服务器返回数据 {"id":1,"value":526000}
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onMsg, this);
        // 初始化卷轴
        for(let i=0; i<this._reelLen; i++) {
            let item = cc.instantiate(this.symbol);
            item.active = true;
            item.parent = this.reel;
            item.idx = i;
            this._symbolItems.push(item);
        }
        this._itemHeight = this._symbolItems[0].height;
        this.setReelPos();
        this.reel.y = -this._itemHeight*this._reelLen/2;
        this._initMoveObj();
    },

    setReelPos() {
        for(let i=0; i<this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            item.y = this._itemHeight/2 + this._itemHeight * i;
        }
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onMsg, false, this);
    },

    _initMoveObj() {
        this._moveObj = {
            round:6,        // 剩余圈数
            minSpeed:50,   // 最小速度/s
            maxSpeed:2400,  // 最大速度/s
            currSpeed:0,    // 当前速度
            acc:15,         // 加速度
            totalDis:0,     // 总移动距离
            movedDis:0,      // 已经移动距离
            canMove:false,  // 是否可移动
            addSpeedPer:0.855, // 加速百分比
        };
        this._moveObj.currSpeed = this._moveObj.minSpeed;
        this._moveObj.totalDis = this._moveObj.round * this._reelLen * this._itemHeight;
    },

    onMsg(msg){
        console.log("#wheeljpgame:", msg);
        if(msg.code == 200 && msg.data.rtype == 1){
            SlotsFacade.soundMgr.playEffect("bonus_wheel_spin");
            this._jpData = msg.data.jackpot;
            this._reelResult = this.genReelData(this._jpData.id-1);
            this._initMoveObj();
            this._moveObj.canMove =true;
        }
    },

    /**
     * 通过jpId 生成卷轴数据
     * @param {*} jpId 
     */
    genReelData(jpId) {
        return ReelCfg[jpId].concat();
    },

    sendMsg(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData._gameId;
        req.data = {rtype:1};
        cc.vv.NetManager.send(req);
    },

    async close() {
        SlotsFacade.mainPanel.showSceneTransition();
        await SlotsFacade.delayTime(1.5);
        this.panel.active = false;
        await SlotsFacade.delayTime(0.5);
        if(SlotsFacade.dm.hasFree()) {

            cc.vv.gameData.GetBottomScript().SetWin(cc.vv.gameData.GetBottomScript().getCurrentWin()+this._jpData.value);
            SlotsFacade.soundMgr.playFreeBgm();
        }else {
            cc.vv.gameData.AddCoin(this._jpData.value);
            await new Promise((sucess, failed)=>{
                this.ShowBottomWin(this._jpData.value,this._jpData.value,true,sucess)
            });
            SlotsFacade.soundMgr.playBgm();
        }
        if(this._cbHandler) {
            this._cbHandler();
        }
    },

    async open(cbHandler) {
        this._cbHandler = cbHandler;
        SlotsFacade.mainPanel.showSceneTransition(()=>{
            SlotsFacade.soundMgr.playBgm("bonus_bgm");
            this.showPopupStart();
        });
        await SlotsFacade.delayTime(1.5)
        this._showJpInfo();
        this.panel.active = true;
        this._initReel();
    },

    _showJpInfo() {
        for(let i=0; i<4; i++) {
            let item = this.jp_node.getChildByName("jp" + i);
            let label = item.getChildByName("lbl_num");
            label.getComponent(cc.Label).string = Global.FormatNumToComma(SlotsFacade.dm.getJpValue(i));
        }
    },

    /**
     * 开始对话框
     */
    async showPopupStart() {
        let panel = this.panel.getChildByName("popup_start");
        panel.active = true;
        // 显示背景
        let bg = panel.getChildByName("bg");
        bg.active = true;
        bg.opacity = 0;
        cc.tween(bg)
            .to(0.3, {opacity:0xff})
            .start();
        // 显示spine
        let spine = panel.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation1", false);
        spine.addAnimation(0, "animation2", true);
        await SlotsFacade.delayTime(0.5);

        await new Promise(res=>{
            let handler = ()=>{
                this.sendMsg();
                SlotsFacade.soundMgr.playEffect("bonus_wheel_click");
                panel.stopAllActions()
                panel.off(cc.Node.EventType.TOUCH_END, handler);
                spine.setAnimation(0, "animation3", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    panel.active = false;
                    res();
                })
            };
            cc.vv.gameData.checkAutoPlay(panel, handler);
            panel.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 初始化卷轴
     */
    _initReel() {
        let reelData = this.genReelData(Math.floor(Math.random()*4));
        let reelDataLen = reelData.length;
        for(let i=0; i<this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            let cmp = item.getComponent("ImgSwitchCmp");
            let jpId = reelData[i%reelDataLen];
            cmp.setIndex(jpId);
        }
    },

    /**
     * 旋转完毕
     */
    async _reelCmp() {
        SlotsFacade.soundMgr.playEffect("bonus_active");
        // 播放中奖标记
        for(let i=0; i<2; i++) {
            let spine = this.win_flag.getChildByName("spine" + (i+1)).getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, "animation", true);
        }
        await SlotsFacade.delayTime(2);
        this.win_flag.getChildByName("spine1").active = false;
        this.win_flag.getChildByName("spine2").active = false;
        await SlotsFacade.popup.showWinJpCoin(this._jpData.id-1, this._jpData.value);
        this.close();
    },

    update(dt) {
        if(!this._moveObj || !this._moveObj.canMove) {
            return;
        }
        // 前1/4距离加速 后1/5距离减速
        let per = this._moveObj.movedDis / this._moveObj.totalDis;
        per = Math.min(per, 1);
        let speed = this._moveObj.currSpeed;
        if(per < this._moveObj.addSpeedPer) {
            speed += this._moveObj.acc;
        }else if(per >= this._moveObj.addSpeedPer) {
            speed -= this._moveObj.acc;
        }
        speed = Math.max(this._moveObj.minSpeed, speed);
        speed = Math.min(this._moveObj.maxSpeed, speed);
        this._moveObj.currSpeed = speed;
        let dis = this._moveObj.currSpeed * dt;
        if(dis > this._itemHeight) {
            dis = this._itemHeight;
        }
        this._moveObj.movedDis += dis;
        // 修改位置
        for(let i=0; i<this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            item.y -= dis;
        }
        // 将超过底边的icon放到最上面
        for(let i=0; i<this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            if(item.y < -this._itemHeight/2) {
                let nextIdx = item.idx - 1;
                if(nextIdx < 0) {
                    nextIdx = this._reelLen - 1;
                }
                let nextItem = this._symbolItems[nextIdx];
                item.y = nextItem.y + this._itemHeight;
                if(item.idx == this._reelLen - 1) {
                    this._moveObj.round -= 1;
                }
                // 最后一圈需要设置结果数据
                if(this._moveObj.round == 0) {
                    let cmp = item.getComponent("ImgSwitchCmp");
                    let jpId = this._reelResult[item.idx%this._reelResult.length];
                    cmp.setIndex(jpId);
                }
                // 转完
                if(this._moveObj.round < 0) {
                    this._moveObj.canMove = false;
                    this._reelCmp();
                }
            }
        }
    }
})