/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal)
            SlotsFacade.mainPanel.showBg(1);
        }
        await this.enterWheelGame();
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 收到spin消息
     * @param {*} msg 
     */
    async onSpinMsg(msg) {
        await SlotsFacade.drumsGame.changeBonusReel();
        await SlotsFacade.drumsGame.hothot();
        SlotsFacade.slots._gameInfo = msg;
        await SlotsFacade.slots.bonusShake();
        SlotsFacade.drumsGame.toNormal();
        SlotsFacade.slots.SetSlotsResult(msg.resultCards);
        SlotsFacade.slots.SetReelStateInfo(msg.resultCards);
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        let bonusCoin = SlotsFacade.dm.getBonusCoin();
        nWin -= bonusCoin;
        nTotal -= bonusCoin;
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
        // 进入bonus游戏
        await this.enterBonusGame();
        await this.enterWheelGame();
        // 控制按钮
        if (SlotsFacade.dm.isTriggerFree()) {
            if(SlotsFacade.dm.isFistTriggerFree()) {
                await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), SlotsFacade.dm.getFreeType());
                SlotsFacade.mainPanel.showSceneTransition();
                await SlotsFacade.delayTime(1.5);
                await this.enterFreeGame();
                SlotsFacade.drumsGame.unlockWheel();
            }
            await SlotsFacade.delayTime(1);
        } else if (cc.vv.gameData.isLastEndFree()) {
            await SlotsFacade.popup.showWinFreeCoin(SlotsFacade.dm.getFreeWinCoin());
            SlotsFacade.mainPanel.showSceneTransition();
            await SlotsFacade.delayTime(1.5);
            await this.enterNormalGame();
        }
        SlotsFacade.slots.CanDoNextRound()
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame() {
        //备份
        SlotsFacade.slots.Backup();

        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.drumsGame.toFreeGame();
        let freeCnt = SlotsFacade.dm.GetFreeTime();
        let freeTotalCnt = SlotsFacade.dm.GetTotalFree();
        SlotsFacade.bottomCmp.ShowFreeModel(true, freeTotalCnt-freeCnt, freeTotalCnt);
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 进入普通游戏
     */
    async enterNormalGame() {
        //恢复
        SlotsFacade.slots.Resume();

        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.soundMgr.playBgm();
        SlotsFacade.drumsGame.toNormalGame();

        if(SlotsFacade.dm.isLastEndFree()) {
            let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nTotal, nTotal,true, res);
            });
        }
    },

    /**
     * 进入bonus游戏
     */
    async enterBonusGame() {
        let spinData = SlotsFacade.dm.getSpinData();
        if(!spinData.bonusResult) {
            return;
        }
        await SlotsFacade.slots.playBonusResult();
    },

    async enterWheelGame() {
        let wheelGame = SlotsFacade.dm.wheelGame;
        if(!wheelGame) {
            return;
        }
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        await new Promise(res=>{
            SlotsFacade.wheelJpGame.open(res);
        });
    }
 })