cc.Class({
    extends: cc.Component,

    properties: {
        symbol:cc.Node,
        select_effect:sp.Skeleton,  // 选中效果
        spine_lock:sp.Skeleton, // 免费icon流光效果

        isLoaded:false,
        val:0, // 当前得值
        type:1, // 1-左边 2-右边
    },

    onLoad() {
        this.symbol = this.node.getChildByName("symbol");
        this.select_effect = this.node.getChildByName("select_effect").getComponent(sp.Skeleton);
        this.select_effect.node.active = false;
        this.spine_lock = this.node.getChildByName("spine_lock").getComponent(sp.Skeleton);
        this.isLoaded = true;
    },

    setType(type) {
        this.type = type;
    },

    /**
     * 播放选中特效
     * @param {*} boo 显示隐藏
     * @param {*} loop 是否循环
     */
    playSelectEffect(boo, loop) {
        this.select_effect.node.active = boo;
        if(boo) {
            loop = loop || false;
            this.select_effect.setAnimation(0, "animation", loop);
        }
    },

    /**
     * 设置解锁状态
     * @param {*} boo 
     */
    setUnlock(boo) {
        boo = boo || false;
        this.spine_lock.node.active = !boo;
        if(!boo) {
            this.spine_lock.setAnimation(0, `animation${this.type}_1`, true);
        }
    },

    /**
     * 变化到解锁
     */
    async toUnlock() {
        this.spine_lock.node.active = true;
        this.spine_lock.setAnimation(0, `animation${this.type}_2`, false);
        this.spine_lock.setCompleteListener(()=>{
            this.spine_lock.setCompleteListener(null);
            this.spine_lock.node.active = false;
        })
    }
})