/**
 * 弹窗管理器
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node
    },

    onLoad() {
        this.bg = this.node.getChildByName("bg");
    },

    showBg(boo) {
        this.bg.active = boo;
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     */
    async showWinFreeCoin(goldNumb) {
        SlotsFacade.soundMgr.playEffect("free_dialog_collect_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_coin");
        panel.active = true;
        panel.scale = 0;
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);

        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        let okBtn = panel.getChildByName("btn_ok");
        okBtn.getComponent(cc.Button).interactable = true;
        await new Promise(res=>{
            let okBtn = panel.getChildByName("btn_ok");
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("common_click");
                okBtn.stopAllActions()
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        okBtn.getComponent(cc.Button).interactable = false;
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示赢取JP金币
     * @param {number} jpType 
     * @param {number} goldNumb 
     */
    async showWinJpCoin(jpType, goldNumb) {
        SlotsFacade.soundMgr.playEffect("win_jp_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("bg").getComponent("ImgSwitchCmp").setIndex(jpType);
        let label = panel.getChildByName("label");
        label.getComponent("LabelRollCmp").startRoll(0, goldNumb);
        panel.getChildByName("label_bg").getComponent("ImgSwitchCmp").setIndex(jpType);
        for(let i=0; i<4; i++) {
            let title = panel.getChildByName("title" + i);
            let titleSpine = panel.getChildByName("title_spine" + i).getComponent(sp.Skeleton);
            if(i == jpType) {
                title.active = true;
                titleSpine.node.active = true;
                titleSpine.setAnimation(0, "animation", true);
            }else {
                title.active = false;
                titleSpine.node.active = false;
            }
        }
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        let okBtn = panel.getChildByName("btn_ok");
        okBtn.getComponent(cc.Button).interactable = true;
        await new Promise(res=>{
            let okBtn = panel.getChildByName("btn_ok");
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("win_jp_click");
                okBtn.stopAllActions()
                okBtn.getComponent(cc.Button).interactable = false;
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示赢取免费次数
     * @param {number} cnt  
     * @param {*} cnt 
     * @param {*} freeType 1-普通免费 2-mega免费 3-super免费
     */
    async showWinFreeCnt(cnt, freeType) {
        freeType = freeType || 1;
        SlotsFacade.soundMgr.playEffect("free_dialog_start_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_cnt");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent(cc.Label).string = cnt+"";
        let uiName = "ui_" + freeType;
        for(let i=0; i<3; i++) {
            let ui = panel.getChildByName("ui_" + (i+1));
            ui.active = ui.name == uiName;
        }

        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await SlotsFacade.delayTime(0.5);

        let okBtn = panel.getChildByName("btn_ok");
        okBtn.getComponent(cc.Button).interactable = true;
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("common_click");
                okBtn.stopAllActions()
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                okBtn.getComponent(cc.Button).interactable = false;
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

 })